import csv, io, json, os, re, sys


def fold(s):
    s = s.casefold()
    s = "".join(ch if ch.isalnum() else " " for ch in s)
    return " ".join(s.split())


def nid(s):
    return s.strip().casefold()


def read_batch(path):
    """Return (batch, revision, status, records) with records = (ballot, contest, {rank: [marks]})
    where a mark is ('c', id) or ('w', text)."""
    with open(path, encoding="utf-8", newline="") as f:
        text = f.read()
    lines = text.split("\n")
    recs = []
    if path.endswith(".jsonl"):
        meta = None
        for ln in lines:
            if not ln.strip():
                continue
            o = json.loads(ln)
            if meta is None:
                meta = o
                continue
            ranks = {}
            for m in o.get("marks", []):
                r = int(m["rank"])
                if m.get("write_in") is not None:
                    mk = ("w", m["write_in"])
                else:
                    mk = ("c", m["candidate"])
                ranks.setdefault(r, []).append(mk)
            recs.append((o["ballot"], o["contest"], ranks))
        meta = meta or {}
    else:
        meta = {}
        i = 0
        while i < len(lines):
            s = lines[i].strip()
            if s.startswith("#"):
                body = s[1:]
                if ":" in body:
                    k, v = body.split(":", 1)
                    meta[k.strip().lower()] = v.strip()
                i += 1
            elif not s:
                i += 1
            else:
                break
        rows = csv.reader(io.StringIO("\n".join(lines[i:])))
        header = None
        for row in rows:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [c.strip() for c in row]
                continue
            d = dict(zip(header, row))
            ranks = {}
            for k, v in d.items():
                mt = re.fullmatch(r"rank(\d+)", k)
                if not mt or v is None or v == "":
                    continue
                marks = []
                for part in v.split("|"):
                    if part.startswith("WI:"):
                        marks.append(("w", part[3:]))
                    elif part.strip():
                        marks.append(("c", part))
                if marks:
                    ranks[int(mt.group(1))] = marks
            recs.append((d["ballot"], d["contest"], ranks))
    return (str(meta.get("batch")), int(str(meta.get("revision", 0)).strip()),
            str(meta.get("status", "final")).strip(), recs)


def prepare(ranks, contest):
    """Return list of rankings: ('skip',) ('pass',) ('choice', c) ('over',)"""
    out = []
    seen = set()
    for r in range(1, contest["max_ranks"] + 1):
        marks = ranks.get(r, [])
        cands = []
        for kind, v in marks:
            if kind == "w":
                c = contest["wi"].get(fold(v))
            else:
                c = nid(v)
            if c is not None and c not in cands:
                cands.append(c)
        if not cands:
            out.append(("skip",))
            continue
        cands = [c for c in cands if c not in contest["withdrawn"]]
        if not cands:
            out.append(("pass",))
            continue
        marked_now = set(cands)
        cands = [c for c in cands if c not in seen]
        seen |= marked_now
        if not cands:
            out.append(("skip",))
        elif len(cands) == 1:
            out.append(("choice", cands[0]))
        else:
            out.append(("over",))
    return out


def read_ballot(rk, continuing):
    n = len(rk)
    for i, x in enumerate(rk):
        t = x[0]
        if t == "choice":
            if x[1] in continuing:
                return x[1]
        elif t == "over":
            return None
        elif t == "skip":
            if i + 1 >= n or rk[i + 1][0] == "skip":
                return None
    return None


def run_contest(contest, ballots):
    ids = contest["ids"]  # normalized -> output id (continuing at start)
    continuing = set(ids)
    res = {"contest": contest["id"], "ballots": len(ballots), "winner": None, "rounds": []}
    history = []
    rnum = 0
    while True:
        rnum += 1
        tally = {c: 0 for c in continuing}
        exhausted = 0
        for rk in ballots:
            c = read_ballot(rk, continuing)
            if c is None:
                exhausted += 1
            else:
                tally[c] += 1
        history.append(dict(tally))
        active = len(ballots) - exhausted
        rd = {"round": rnum, "tallies": {ids[c]: v for c, v in tally.items()},
              "exhausted": exhausted, "eliminated": []}
        res["rounds"].append(rd)
        if active == 0:
            break
        win = None
        for c, v in tally.items():
            if v * 2 > active:
                win = c
        if win is None and len(continuing) == 1:
            win = next(iter(continuing))
        if win is not None:
            res["winner"] = ids[win]
            break
        zeros = [c for c, v in tally.items() if v == 0]
        if zeros:
            elim = zeros
        else:
            m = min(tally.values())
            tied = [c for c, v in tally.items() if v == m]
            k = len(history) - 2
            while len(tied) > 1 and k >= 0:
                mm = min(history[k][c] for c in tied)
                tied = [c for c in tied if history[k][c] == mm]
                k -= 1
            if len(tied) > 1:
                lot = contest["lot"]
                tied.sort(key=lambda c: lot.get(c, -1))
                tied = [tied[-1]]
            elim = tied
        rd["eliminated"] = sorted(ids[c] for c in elim)
        continuing -= set(elim)
    return res


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, "election.json"), encoding="utf-8") as f:
        el = json.load(f)
    contests = {}
    for c in el["contests"]:
        ids, withdrawn, wi = {}, set(), {}
        for cd in c.get("candidates", []):
            n = nid(cd["id"])
            if cd.get("status", "active") == "withdrawn":
                withdrawn.add(n)
            else:
                ids[n] = cd["id"]
        for w in c.get("write_ins", []):
            n = nid(w["id"])
            ids[n] = w["id"]
            for t in [w["name"]] + list(w.get("aliases", [])):
                wi.setdefault(fold(t), n)
        lot = {nid(x): i for i, x in enumerate(c.get("lot_order", []))}
        contests[c["id"]] = {"id": c["id"], "max_ranks": c["max_ranks"], "ids": ids,
                             "withdrawn": withdrawn, "wi": wi, "lot": lot}
    cvr = os.path.join(inp, "cvr")
    best = {}
    for name in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, name)
        if not os.path.isfile(p) or not name.endswith((".csv", ".jsonl")):
            continue
        b, rev, st, recs = read_batch(p)
        if b not in best or rev > best[b][0]:
            best[b] = (rev, st, recs)
    ballots = {k: [] for k in contests}
    for rev, st, recs in best.values():
        if st == "void":
            continue
        for _, cid, ranks in recs:
            if cid in contests:
                ballots[cid].append(prepare(ranks, contests[cid]))
    out = {"election": el["election"],
           "contests": [run_contest(contests[c["id"]], ballots[c["id"]]) for c in el["contests"]]}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)


main()
